<script setup lang="ts">
import {ref,computed} from 'vue'
import AppShell from '../components/AppShell.vue'
import PointBalance from '../components/PointBalance.vue'
import StatusPill from '../components/StatusPill.vue'
import EmptyState from '../components/EmptyState.vue'
import LoadMore from '../components/LoadMore.vue'
import {usePage} from '../composables/usePage'
import {get,getAll,mutate,childPath,familyPath} from '../services/api'
import {go} from '../services/navigation'
import {businessDate,daysAgo,dateTime,label,integer,displayOperator} from '../services/format'
import type {Child,Account,LedgerEntry,Occurrence,Order,AuditEntry,Growth,PageResult,Today} from '../services/types'
const props=defineProps<{page:string;query:Record<string,string>}>();const childPage=props.page==='growth'
const children=ref<Child[]>([]),childId=ref(props.query.childId||''),account=ref<Account|null>(null),entries=ref<LedgerEntry[]>([]),occurrences=ref<Occurrence[]>([]),orders=ref<Order[]>([]),audits=ref<AuditEntry[]>([]),growth=ref<Growth|null>(null),tab=ref(props.query.record==='true'?'record':props.page==='growth'?'ledger':'activities'),dateFrom=ref(daysAgo(29)),dateTo=ref(businessDate()),recordDate=ref(businessDate()),type=ref(''),status=ref(''),cursor=ref<string|null>(null),hasMore=ref(false),points=ref('5'),reason=ref(''),selected=ref<LedgerEntry|null>(null),expanded=ref('')
const titles:Record<string,string>={ledger:'每一分，都有来处',history:'家庭记录',growth:'我的小小成长'}
const {loading,error,busy,reload,act,session}=usePage(props.page,load,childPage?'child':'guardian')
const currentChild=computed(()=>childId.value||session.view?.childId||'')
async function load(){if(!childPage){children.value=await getAll<Child>(familyPath('/children'));if(!childId.value&&children.value.length)childId.value=children.value[0].id}if(props.page==='ledger'||props.page==='growth'){if(!currentChild.value)return;account.value=await get<Account>(childPath(currentChild.value,'/account'));if(props.page==='growth')growth.value=await get<Growth>(childPath(currentChild.value,'/growth'),{dateFrom:dateFrom.value,dateTo:dateTo.value});if(tab.value==='activities')await loadHistory();else await loadLedger()}else await loadHistory()}
async function loadLedger(more=false){const result=await get<PageResult<LedgerEntry>>(childPath(currentChild.value,'/ledger'),{type:type.value||undefined,dateFrom:dateFrom.value,dateTo:dateTo.value,cursor:more?cursor.value:undefined});entries.value=more?[...entries.value,...result.items]:result.items;cursor.value=result.nextCursor||null;hasMore.value=result.hasMore}
async function loadHistory(more=false){if(tab.value==='audit'){const result=await get<PageResult<AuditEntry>>(familyPath('/audit-logs'),{dateFrom:dateFrom.value,dateTo:dateTo.value,childId:childId.value||undefined,cursor:more?cursor.value:undefined});audits.value=more?[...audits.value,...result.items]:result.items;cursor.value=result.nextCursor||null;hasMore.value=result.hasMore;return}if(!currentChild.value)return;if(tab.value==='orders'){const result=await get<PageResult<Order>>(childPath(currentChild.value,'/orders'),{status:status.value||undefined,cursor:more?cursor.value:undefined});orders.value=more?[...orders.value,...result.items]:result.items;cursor.value=result.nextCursor||null;hasMore.value=result.hasMore;return}if(tab.value==='record'){const result=await get<Today>(childPath(currentChild.value,'/today'),{businessDate:recordDate.value});occurrences.value=[...result.routines,...result.challenges];hasMore.value=false;return}const result=await get<PageResult<Occurrence>>(childPath(currentChild.value,'/history'),{dateFrom:dateFrom.value,dateTo:dateTo.value,type:type.value||undefined,status:status.value||undefined,cursor:more?cursor.value:undefined});occurrences.value=more?[...occurrences.value,...result.items]:result.items;cursor.value=result.nextCursor||null;hasMore.value=result.hasMore}
async function refreshRecords(){cursor.value=null;await load()}
async function praise(){await act(async()=>{if(!currentChild.value)throw new Error('请选择孩子');if(!integer(points.value,1,1000)||!reason.value.trim())throw new Error('请填写1—1,000整数积分和具体表扬原因');const result=await mutate<{account:Account}>('POST',childPath(currentChild.value,'/praises'),{points:Number(points.value),reason:reason.value.trim()},'手动表扬孩子');account.value=result.account;reason.value='';await loadLedger()},'表扬积分已到账')}
async function reverse(){await act(async()=>{if(!selected.value||!account.value)return;if(!reason.value.trim())throw new Error('请说明这次记录为什么需要纠正');if(account.value.availablePoints<selected.value.availableDelta)throw new Error('可用积分不足，不能使用预留积分或制造负余额');await mutate('POST',familyPath(`/ledger/${selected.value.id}/reversal`),{reason:reason.value.trim(),expectedAccountVersion:account.value.version},'完整撤销错误发奖');selected.value=null;reason.value='';await load()},'原记录已完整撤销，历史保留')}
function more(){return props.page==='ledger'||props.page==='growth'&&tab.value==='ledger'?loadLedger(true):loadHistory(true)}
const ledgerTab=computed(()=>props.page==='ledger'||props.page==='growth'&&tab.value==='ledger')
const auditName=(action:string)=>({FAMILY_CREATED:'创建家庭',CHILD_CREATED:'添加孩子',PLAN_CREATED:'创建计划',PLAN_PUBLISHED:'发布计划',OCCURRENCE_SUBMITTED:'提交完成',OCCURRENCE_APPROVED:'通过完成',ORDER_CREATED:'申请奖励',ORDER_APPROVED:'批准兑换',ORDER_FULFILLED:'实际兑现',ORDER_CANCELED:'取消兑换',PRAISE_GRANTED:'手动表扬'} as Record<string,string>)[action]||label(action)
</script>
<template><AppShell :title="titles[page]" :tab="childPage?'growth':''" :back="!childPage" :loading="loading" :error="error" @retry="reload"><view v-if="!childPage" class="field"><text class="field-label">孩子</text><picker :range="children.map(c=>c.nickname)" :value="Math.max(0,children.findIndex(c=>c.id===childId))" @change="childId=children[Number($event.detail.value)]?.id;act(refreshRecords)"><view class="select-control">{{children.find(c=>c.id===childId)?.nickname||'请先添加孩子'}}</view></picker></view><PointBalance v-if="page!=='history'" :account="account"/><view v-if="page==='growth'&&growth" class="card"><text class="caption">{{dateFrom}} — {{dateTo}}</text><view class="row between section"><view><text class="card-title">{{growth.points?.earned??'—'}}</text><text class="caption">这段时间赚取</text></view><view><text class="card-title">{{growth.points?.spent??'—'}}</text><text class="caption">这段时间兑换支出</text></view></view><text class="caption section">赚取不包含退款或预留释放；日常和挑战分别统计。</text></view><view v-if="page!=='ledger'" class="tabs"><button v-if="childPage" :class="{active:tab==='ledger'}" @tap="tab='ledger';type='';status='';act(refreshRecords)">积分明细</button><button :class="{active:tab==='activities'}" @tap="tab='activities';type='';status='';act(refreshRecords)">完成记录</button><button v-if="!childPage" :class="{active:tab==='record'}" @tap="tab='record';act(refreshRecords)">代录补记</button><button v-if="!childPage" :class="{active:tab==='orders'}" @tap="tab='orders';status='';act(refreshRecords)">兑换</button><button v-if="!childPage" :class="{active:tab==='audit'}" @tap="tab='audit';act(refreshRecords)">操作记录</button></view><view v-if="tab==='record'" class="field"><text class="field-label">选择真实发生日期</text><picker mode="date" :start="daysAgo(7)" :end="businessDate()" :value="recordDate" @change="recordDate=$event.detail.value;act(refreshRecords)"><view class="select-control">{{recordDate}}</view></picker><text class="caption">日常支持今天和过去7个业务日，共8个日期；只能补真实存在的适用实例。</text></view><view v-else class="button-row"><picker mode="date" :value="dateFrom" :end="dateTo" @change="dateFrom=$event.detail.value;act(refreshRecords)"><view class="select-control">起 {{dateFrom}}</view></picker><picker mode="date" :value="dateTo" :start="dateFrom" :end="businessDate()" @change="dateTo=$event.detail.value;act(refreshRecords)"><view class="select-control">止 {{dateTo}}</view></picker></view><template v-if="ledgerTab"><view class="chip-row"><button v-for="t in ['','ACTIVITY_AWARD','PRAISE','ORDER_HOLD','ORDER_CAPTURE','ORDER_RELEASE','ORDER_REFUND','AWARD_REVERSAL']" :key="t||'all'" class="chip" :class="{active:type===t}" @tap="type=t;act(()=>loadLedger())">{{t?label(t):'全部'}}</button></view><view v-for="entry in entries" :key="entry.id" class="card" @tap="expanded=expanded===entry.id?'':entry.id"><view class="row between"><view class="grow"><text class="card-title">{{label(entry.type)}}</text><text class="caption">{{entry.reason||'查看关联记录'}} · {{dateTime(entry.createdAt)}}</text></view><view><text class="points">可用 {{entry.availableDelta>0?'+':''}}{{entry.availableDelta}}</text><text class="caption">预留 {{entry.heldDelta>0?'+':''}}{{entry.heldDelta}}</text></view></view><template v-if="expanded===entry.id"><view class="summary section"><view class="summary-row"><text class="summary-label">变动后可用 / 预留</text><text class="summary-value">{{entry.availableAfter}} / {{entry.heldAfter}}</text></view><view class="summary-row"><text class="summary-label">操作人</text><text class="summary-value">{{displayOperator(entry.operatorSummary)}}</text></view><view class="summary-row"><text class="summary-label">账户版本</text><text class="summary-value">{{entry.accountVersion}}</text></view></view><text v-if="entry.reversalOfId" class="caption section">更正原记录 {{entry.reversalOfId}}</text><button v-if="!session.isFamilyReadOnly&&!childPage&&['ACTIVITY_AWARD','PRAISE'].includes(entry.type)&&!entry.reversed&&entry.availableDelta>0" class="danger-button full section" @tap.stop="selected=entry;reason=''">纠正这次记录（完整撤销）</button></template></view><EmptyState v-if="!entries.length&&!loading" title="这段时间没有积分记录" description="每一次入账、预留和兑换都会在这里说明。"/><LoadMore :has-more="hasMore" :loading="busy" @more="act(more)"/><view v-if="!session.isFamilyReadOnly&&!childPage&&children.find(c=>c.id===childId)?.status==='ACTIVE'" class="card section"><text class="section-title">给一次具体的表扬</text><view class="field"><text class="field-label">增加积分</text><input class="input" v-model="points" type="number"/></view><view class="field"><text class="field-label">表扬原因（必填）</text><textarea class="textarea" v-model="reason" maxlength="200" placeholder="说清楚值得肯定的具体行为"/></view><button :class="{'is-disabled':(busy||!!account?.grantBlockedByCap||!!account?.frozen)}" class="primary full" :disabled="busy||!!account?.grantBlockedByCap||!!account?.frozen" :loading="busy" @tap="praise">确认表扬并加分</button><text v-if="account?.grantBlockedByCap" class="field-error">当前总持有达到新发分上限，暂不能继续发分。</text></view><view v-if="selected" class="card section"><text class="section-title">完整撤销{{selected.availableDelta}}积分</text><view class="notice warning section">仅用于纠正错误记录，不是惩罚。原记录不会被删除，同一笔只能撤销一次。</view><text class="body-copy">当前可用{{account?.availablePoints}}积分，申请预留不参与撤销。</text><textarea v-model="reason" class="textarea section" maxlength="200" placeholder="请说明纠正原因"/><button :class="{'is-disabled':(busy||(account?.availablePoints??0)<selected.availableDelta)}" class="danger-button full section" :loading="busy" :disabled="busy||(account?.availablePoints??0)<selected.availableDelta" @tap="reverse">确认完整撤销</button><text v-if="(account?.availablePoints??0)<selected.availableDelta" class="field-error">可用积分不足，无法撤销。</text><button class="text-button full" @tap="selected=null;reason=''">不修改这条记录</button></view></template>
<template v-else-if="tab==='activities'||tab==='record'"><view v-if="tab==='activities'" class="chip-row"><button v-for="t in ['','ROUTINE','CHALLENGE']" :key="t||'all'" class="chip" :class="{active:type===t}" @tap="type=t;act(()=>loadHistory())">{{t?label(t):'全部类型'}}</button></view><view v-if="tab==='activities'" class="chip-row"><button v-for="s in ['','OPEN','SUBMITTED','NEEDS_CHANGES','APPROVED','EXEMPTED','REVOKED']" :key="s||'all'" class="chip" :class="{active:status===s}" @tap="status=s;act(()=>loadHistory())">{{s?label(s):'全部状态'}}</button></view><view v-for="o in occurrences" :key="o.id" class="card" @tap="go(childPage?'activity':'occurrence',{id:o.id})"><view class="row between"><text class="card-title">{{o.snapshot.title}}</text><StatusPill :status="o.displayState||o.status"/></view><text class="caption">{{label(o.type)}} · {{o.businessDate||dateTime(o.startsAt)}} · {{o.snapshot.awardPoints}}积分</text><text v-if="o.supplementUntil" class="caption">补充截止 {{dateTime(o.supplementUntil)}}</text><button class="text-button">{{tab==='record'?'查看并记录完成':'查看详情'}} →</button></view><EmptyState v-if="!occurrences.length&&!loading" :title="tab==='record'?'这一天没有适用任务':'这段时间没有完成记录'" description="未曾安排的事项不会算成漏做，也不会产生补记奖励。"/><LoadMore :has-more="hasMore" :loading="busy" @more="act(more)"/></template>
<template v-else-if="tab==='orders'"><view class="chip-row"><button v-for="s in ['','PENDING_APPROVAL','READY','FULFILLED','CANCELED','REJECTED','EXPIRED']" :key="s||'all'" class="chip" :class="{active:status===s}" @tap="status=s;act(()=>loadHistory())">{{s?label(s):'全部'}}</button></view><view v-for="o in orders" :key="o.id" class="card" @tap="go('order',{id:o.id})"><view class="row between"><text class="card-title">{{o.rewardSnapshot.name}}</text><StatusPill :status="o.status"/></view><text class="caption">{{o.costPointsSnapshot}}积分 · 申请 {{dateTime(o.createdAt)}}</text></view><EmptyState v-if="!orders.length&&!loading" title="没有兑换记录" description="每一份申请和兑现都会留下记录。"/><LoadMore :has-more="hasMore" :loading="busy" @more="act(more)"/></template>
<template v-else-if="tab==='audit'"><view v-for="a in audits" :key="a.id" class="card"><text class="card-title">{{auditName(a.action)}}</text><text class="caption">{{a.operatorName||displayOperator(a.operatorSummary)}} · {{dateTime(a.createdAt)}}</text><text v-if="a.reason||a.details?.reason" class="body-copy">{{a.reason||a.details?.reason}}</text><text v-if="a.targetId||a.sourceId" class="caption section">关联记录 {{a.targetId||a.sourceId}}</text><text v-if="a.requestId" class="caption">请求号 {{a.requestId}}</text></view><EmptyState v-if="!audits.length&&!loading" title="这段时间没有操作记录" description="家长的业务操作会在这里留痕。"/><LoadMore :has-more="hasMore" :loading="busy" @more="act(more)"/></template><button v-if="childPage&&!session.isDelegated" class="secondary full section" @tap="go('account')">我的账号与隐私</button></AppShell></template>
